module x_oracle::x_oracle;

use std::type_name::{Self, TypeName};
use sui::dynamic_field;
use sui::package;
use sui::table::{Self, Table};
use sui::clock::Clock;

use pyth::price_info::PriceInfoObject;

use x_oracle::price_feed::{Self, PriceFeed, PriceFeedComponent};
use x_oracle::pyth_adaptor::{Self, PythFeedData};
use x_oracle::oracle_error; 

public struct AdminCap has key, store {
    id: UID,
}

public struct X_ORACLE has drop {}

// This tracks the list of base tokens for oracle price feed quotes. 
// Given different base token, the price feed might be created differently. For example,
// lstSui vs Sui will have a different price feed reporting mechanism compared to say 
// lstSui vs USD.
public struct BaseToken has drop, copy, store {
    id: u8,
}

const CURRENT_VERSION: u64 = 0;
const MAX_DELAY_TOLERANCE_MS: u64 = 1800000;

const USD: u8 = 0;
// const SUI: u8 = 1;


public struct XOracle has key {
    id: UID,

    price_delay_tolerance_ms: u64,
    prices: Table<BaseToken, Table<TypeName, PriceFeed>>,

    version: u64,

    // dynamic fields:
    // - pyth_price_feeds: Table<TypeName, PythFeedData>
}

fun init(otw: X_ORACLE, ctx: &mut TxContext) {
    package::claim_and_keep(otw, ctx);

    let x_oracle = new(ctx);
    transfer::share_object(x_oracle);

    let admin_cap = AdminCap { id: object::new(ctx) };
    transfer::transfer(admin_cap, ctx.sender());
}

fun new(ctx: &mut TxContext): XOracle {
    let mut x_oracle = XOracle {
        id: object::new(ctx),
        prices: table::new(ctx),
        // default delay is 5 seconds
        price_delay_tolerance_ms: 5000,
        version: CURRENT_VERSION,
    };

    x_oracle.prices.add(usd(), table::new(ctx));

    let pyth_price_feeds: Table<TypeName, PythFeedData> = table::new(ctx);
    dynamic_field::add(&mut x_oracle.id, PythPriceFeedKey {}, pyth_price_feeds);

    x_oracle
}

public fun usd(): BaseToken { BaseToken { id: USD } }
// public(package) fun sui(): BaseToken { BaseToken { id: SUI } }

public fun base_token_from_u8(id: u8): BaseToken {
    match (id) {
        USD => usd(),
        _ => {
            abort x_oracle::oracle_error::unknown_oracle_base_token()
        }
    }
}

public fun price(self: &XOracle, coin_type: TypeName, base_token: BaseToken): &PriceFeed { 
    let BaseToken { id } = base_token;

    match (id) {
        USD => usd_price(self, coin_type),
        _ => {
            abort x_oracle::oracle_error::unknown_oracle_base_token()
        }
    }
}

public(package) fun ensure_version_matches(self: &XOracle) {
    assert!(self.version == CURRENT_VERSION, oracle_error::version_not_match());
}

public(package) fun migrate(self: &mut XOracle): u64 {
    // only sequential migrate is allowed
    assert!(self.version < CURRENT_VERSION, oracle_error::version_not_match());
    self.version = CURRENT_VERSION;

    CURRENT_VERSION
}

// refresh pyth price feed, note that we are updating against usd prices
public(package) fun refresh_usd_price<CoinType>(
    x_oracle: &mut XOracle,
    price_info_object: &PriceInfoObject,
    clock: &Clock,
) {
    let pyth_feed_infos = x_oracle.pyth_price_feeds();

    let coin_type = type_name::with_defining_ids<CoinType>();
    let feed_data = pyth_feed_infos.borrow(coin_type);

    // Make sure the price info object is the registerred one for the coin type
    feed_data.assert_pyth_price_info_object(price_info_object);

    let (ema, spot) = pyth_adaptor::get_pyth_price(price_info_object, feed_data, clock);

    update_price_feed(
        x_oracle,

        usd(),
        coin_type,

        spot,
        ema,
    );
}

public(package) fun price_delay_tolerance_ms(self: &XOracle): u64 { self.price_delay_tolerance_ms }

public(package) fun pyth_price_feeds(self: &XOracle): &Table<TypeName, PythFeedData> { 
    dynamic_field::borrow(&self.id, PythPriceFeedKey {})
}

// mutable functions for admin purposes
public(package) fun pyth_price_feeds_mut(self: &mut XOracle): &mut Table<TypeName, PythFeedData> { 
    dynamic_field::borrow_mut(&mut self.id, PythPriceFeedKey {})
}

public(package) fun update_price_delay_tolerance_ms(self: &mut XOracle, price_delay_tolerance_ms: u64) {
    assert!(price_delay_tolerance_ms <= MAX_DELAY_TOLERANCE_MS, oracle_error::invalid_delay_tolerance());
    self.price_delay_tolerance_ms = price_delay_tolerance_ms;
}

fun usd_price(self: &XOracle, coin_type: TypeName): &PriceFeed { 
   let prices: &Table<TypeName, PriceFeed> = self.prices.borrow(usd());

    assert!(prices.contains(coin_type), x_oracle::oracle_error::oracle_price_not_found_error());
    prices.borrow(coin_type)
}

fun update_price_feed(
    self: &mut XOracle,

    base_token: BaseToken,
    coin_type: TypeName,

    spot: PriceFeedComponent,
    ema: PriceFeedComponent,
) {
    let base_token_prices = self.prices.borrow_mut(base_token);

    if (!base_token_prices.contains(coin_type)) {
        let price_feed = price_feed::new(spot, ema);
        base_token_prices.add(coin_type, price_feed);
    } else {
        let feed = base_token_prices.borrow_mut(coin_type);
        feed.set(spot, ema);
    };
}

public struct PythPriceFeedKey has copy, drop, store {}

#[test_only]
public fun init_t(ctx: &mut TxContext) {
    init(X_ORACLE {}, ctx);
}

#[test_only]
public fun update_price<T>(self: &mut XOracle, clock: &Clock, value: u64) {
    let coin_type = std::type_name::with_defining_ids<T>();

    let time = sui::clock::timestamp_ms(clock) / 1000;

    let ema = x_oracle::price_feed::new_component(value, time);
    let spot = x_oracle::price_feed::new_component(value, time);

    update_price_feed(
        self,

        usd(),
        coin_type,

        spot,
        ema,
    );
}

